<div class="panel"><table><thead><tr><th>Nama Obat</th><th>Kategori</th><th>Stok</th><th>Satuan</th><th>Harga</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php $q=$conn->query("SELECT * FROM obat ORDER BY nama");while($r=$q->fetch_assoc()):?><tr><td><b><?=$r["nama"]?></b></td><td><?=$r["kategori"]?></td><td><?=$r["stok"]?></td><td><?=$r["satuan"]?></td><td>Rp <?=number_format($r["harga"],0,",",".")?></td><td><span class="<?=$r["stok"]<10?"badge pending":"status"?>"><?=$r["stok"]<10?"Stok menipis":"Tersedia"?></span></td><td class="actions-cell"><a class="edit" href="?edit=<?=$r["id"]?>">Edit</a><a class="delete" onclick="return confirm('Hapus obat?')" href="?delete=<?=$r["id"]?>">Hapus</a></td></tr><?php endwhile;?></tbody></table></div><?php require "../includes/footer.php";?>